                            </tr>
                        </thead>
                        <tbody>
                            {items.map((item) => {
                                const reembolsoItem = item.km * valorPorKm;
                                const totalItem = reembolsoItem + item.toll;

                                return (
                                    <tr key={item.id} className="text-center group hover:bg-gray-50">
                                        <td className="border border-gray-300 p-0">
                                            <input 
                                                type="date" 
                                                className="w-full h-full p-2 text-center outline-none bg-transparent"
                                                value={item.date}
                                                onChange={(e) => handleItemChange(item.id, 'date', e.target.value)}
                                            />
                                        </td>
                                        <td className="border border-gray-300 p-0">
                                            <input 
                                                type="text" 
                                                className="w-full h-full p-2 outline-none bg-transparent"
                                                value={item.description}
                                                onChange={(e) => handleItemChange(item.id, 'description', e.target.value)}
                                            />
                                        </td>
                                        <td className="border border-gray-300 p-0">
                                            <input 
                                                type="text" 
                                                className="w-full h-full p-2 outline-none bg-transparent"
                                                value={item.origin}
                                                onChange={(e) => handleItemChange(item.id, 'origin', e.target.value)}
                                            />
                                        </td>
                                        <td className="border border-gray-300 p-0">
