                             <span className="text-gray-400 dark:text-gray-500">• Opção Principal: {data.principalVariantName}</span>
                        )}
                    </p>
                </div>
                <div className="flex items-center gap-2">
                    <p className="font-semibold text-xl text-indigo-600 dark:text-indigo-400 hidden sm:block">
                        {formatCurrency(data.displayPrice)}
