                    aria-label="Editar orçamento"
                    >
                    <EditIcon className="w-5 h-5" />
                    </button>
                    <button
                    onClick={(e) => { e.stopPropagation(); handleDeleteClick(orc.id); }}
                    className="p-2 text-gray-500 hover:text-red-600 dark:text-gray-400 dark:hover:text-red-400 rounded-full hover:bg-red-100 dark:hover:bg-red-900/50 transition-colors"
                    aria-label="Excluir orçamento"
                    >
                    <TrashIcon className="w-5 h-5" />
