  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [editingOrcamento, setEditingOrcamento] = useState<SavedOrcamento | null>(null);

  // State for Editing Expense Reports
  const [editingReport, setEditingReport] = useState<ExpenseReport | null>(null);

  const handleSetCurrentPage = (page: Page) => {
    // Clear editing states when navigating away or explicitly to 'New'
    if (page !== 'NOVO_ORCAMENTO') {
        setEditingOrcamento(null);
    }
    if (page === 'RELATORIOS_NOVO') {
        setEditingReport(null);
    }
    setCurrentPage(page);
  }

  const handleEditOrcamento = (orcamento: SavedOrcamento) => {
    setEditingOrcamento(orcamento);
    setCurrentPage('NOVO_ORCAMENTO');
  };

  const handleEditReport = (report: ExpenseReport) => {
      setEditingReport(report);
      setCurrentPage('RELATORIOS_NOVO');
  }

  const handleSaveReport = () => {
      setEditingReport(null);
      setCurrentPage('RELATORIOS_HISTORICO');
  }

  const renderPage = () => {
    switch (currentPage) {
      case 'ORCAMENTO':
        return <OrcamentoPage setCurrentPage={handleSetCurrentPage} onEdit={handleEditOrcamento} />;
      case 'NOVO_ORCAMENTO':
        return <NovoOrcamentoPage 
                    setCurrentPage={handleSetCurrentPage} 
                    orcamentoToEdit={editingOrcamento}
                    clearEditingOrcamento={() => setEditingOrcamento(null)}
                />;
      case 'FINANCEIRO_VISAO_GERAL':
        return <FinanceiroPage view="dashboard" />;
      case 'FINANCEIRO_DRE':
        return <FinanceiroPage view="dre" />;
      case 'FINANCEIRO_CATEGORIAS':
        return <FinanceiroPage view="categorias" />;
      case 'ESTOQUE_VISAO_GERAL':
        return <EstoquePage view="dashboard" setCurrentPage={handleSetCurrentPage} />;
      case 'ESTOQUE_NOVO_PRODUTO':
        return <EstoquePage view="cadastro" setCurrentPage={handleSetCurrentPage} />;
      case 'ESTOQUE_COMPRAS':
        return <EstoquePage view="compras" setCurrentPage={handleSetCurrentPage} />;
      case 'RELATORIOS_VISAO_GERAL':
        return <RelatoriosPage view="analise" />;
      case 'RELATORIOS_NOVO':
        return <RelatoriosPage view="reembolso" reportToEdit={editingReport} onSave={handleSaveReport} />;
      case 'RELATORIOS_STATUS':
        return <RelatoriosPage view="status" onEditReport={handleEditReport} />;
      case 'RELATORIOS_HISTORICO':
        return <RelatoriosPage view="historico" onEditReport={handleEditReport} />;
      case 'RELATORIOS_CONFIG':
        return <RelatoriosPage view="config" />;
      case 'USUARIOS_GESTAO':
        return <UsuariosPage view="gestao" />;
      case 'USUARIOS_PERFIS':
        return <UsuariosPage view="perfis" />;
      case 'USUARIOS': // Fallback legacy
        return <UsuariosPage view="gestao" />;
      case 'DASHBOARD':
      default:
        return <DashboardPage />;
    }
  };

  const getPageTitle = () => {
    if (currentPage === 'NOVO_ORCAMENTO') {
      return editingOrcamento ? 'Editar Orçamento' : 'Novo Orçamento';
    }
    const titles: Record<string, string> = {
      DASHBOARD: 'Dashboard',
      ORCAMENTO: 'Listar Orçamentos',
      NOVO_ORCAMENTO: 'Novo Orçamento',
      FINANCEIRO_VISAO_GERAL: 'Financeiro',
      FINANCEIRO_DRE: 'Demonstrativo de Resultado (DRE)',
      FINANCEIRO_CATEGORIAS: 'Categorias Financeiras',
      ESTOQUE_VISAO_GERAL: 'Estoque',
      ESTOQUE_NOVO_PRODUTO: 'Cadastro de Produto',
      ESTOQUE_COMPRAS: 'Solicitação de Compra',
      RELATORIOS_VISAO_GERAL: 'Análise de Despesas',
      RELATORIOS_NOVO: editingReport ? 'Editar Relatório' : 'Novo Relatório de Reembolso',
      RELATORIOS_STATUS: 'Status de Pagamento',
      RELATORIOS_HISTORICO: 'Histórico de Despesas',
      RELATORIOS_CONFIG: 'Configuração de Reembolso',
      USUARIOS_GESTAO: 'Gestão de Usuários',
      USUARIOS_PERFIS: 'Perfis de Acesso',
    };
    return titles[currentPage] || 'Orner';
  };


  return (
    <div className="flex h-screen bg-gray-100 dark:bg-gray-900 text-gray-800 dark:text-gray-200">
      <Sidebar currentPage={currentPage} setCurrentPage={handleSetCurrentPage} isSidebarOpen={isSidebarOpen} setSidebarOpen={setSidebarOpen} />
      <div className="flex-1 flex flex-col overflow-hidden min-w-0">
        <Header 
          title={getPageTitle()}
          onMenuClick={() => setSidebarOpen(!isSidebarOpen)}
        />
        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-100 dark:bg-gray-900 p-4 sm:p-6 md:p-8">
          {renderPage()}
        </main>
      </div>
    </div>
  );
};

export default App;
]]></content>
