    <content><![CDATA[
import React, { useState, useEffect } from 'react';
import Modal from '../components/Modal';
import { AddIcon, EditIcon, TrashIcon, UsersIcon, LockClosedIcon, BadgeIcon, UserGroupIcon } from '../assets/icons';
import type { User, AccessProfile, UsuariosPageProps } from '../types';
import { MOCK_USERS, MOCK_PROFILES, MENU_ITEMS } from '../constants';

const UsuariosPage: React.FC<UsuariosPageProps> = ({ view }) => {
    // --- STATE ---
    const [users, setUsers] = useState<User[]>([]);
    const [profiles, setProfiles] = useState<AccessProfile[]>([]);

    // User Modal State
    const [isUserModalOpen, setUserModalOpen] = useState(false);
    const [editingUser, setEditingUser] = useState<User | null>(null);
    const [userFormData, setUserFormData] = useState<Partial<User>>({
        name: '',
        email: '',
        profileId: '',
        active: true,
    });

    // Profile Modal State
    const [isProfileModalOpen, setProfileModalOpen] = useState(false);
    const [editingProfile, setEditingProfile] = useState<AccessProfile | null>(null);
    const [profileFormData, setProfileFormData] = useState<Partial<AccessProfile>>({
        name: '',
        permissions: []
    });

    // --- EFFECTS ---
    useEffect(() => {
        const savedUsers = localStorage.getItem('system_users');
        if (savedUsers) {
            setUsers(JSON.parse(savedUsers));
        } else {
            setUsers(MOCK_USERS);
        }

        const savedProfiles = localStorage.getItem('system_profiles');
        if (savedProfiles) {
            setProfiles(JSON.parse(savedProfiles));
        } else {
            setProfiles(MOCK_PROFILES);
        }
    }, []);

    useEffect(() => {
        localStorage.setItem('system_users', JSON.stringify(users));
    }, [users]);

    useEffect(() => {
        localStorage.setItem('system_profiles', JSON.stringify(profiles));
    }, [profiles]);

    // --- HANDLERS: USER ---
    const handleOpenUserModal = (user?: User) => {
        if (user) {
            setEditingUser(user);
            setUserFormData({ ...user });
        } else {
            setEditingUser(null);
            setUserFormData({
                name: '',
                email: '',
                profileId: '',
                active: true,
            });
        }
        setUserModalOpen(true);
    };

    const handleSaveUser = (e: React.FormEvent) => {
        e.preventDefault();

        if (!userFormData.name || !userFormData.email || !userFormData.profileId) {
            alert('Preencha os campos obrigatórios (Nome, Email e Perfil).');
            return;
        }

        // Inherit permissions from selected profile
        const selectedProfile = profiles.find(p => p.id === userFormData.profileId);
        const inheritedPermissions = selectedProfile ? selectedProfile.permissions : [];

        const newUser: User = {
            id: editingUser ? editingUser.id : Date.now().toString(),
            name: userFormData.name!,
            email: userFormData.email!,
            role: selectedProfile?.id === 'admin' ? 'admin' : 'user', // Basic role mapping
            active: userFormData.active ?? true,
            profileId: userFormData.profileId,
            permissions: inheritedPermissions, // Permission cache
            avatar: editingUser?.avatar || `https://ui-avatars.com/api/?name=${encodeURIComponent(userFormData.name!)}&background=random`
        };

        if (editingUser) {
            setUsers(prev => prev.map(u => u.id === editingUser.id ? newUser : u));
        } else {
            setUsers(prev => [...prev, newUser]);
        }

        setUserModalOpen(false);
    };

    const handleDeleteUser = (id: string) => {
        if (window.confirm('Tem certeza que deseja excluir este usuário?')) {
            setUsers(prev => prev.filter(u => u.id !== id));
        }
    };

    // --- HANDLERS: PROFILE ---
    const handleOpenProfileModal = (profile?: AccessProfile) => {
        if (profile) {
            setEditingProfile(profile);
            setProfileFormData({ ...profile });
        } else {
            setEditingProfile(null);
            setProfileFormData({
                name: '',
                permissions: []
            });
        }
        setProfileModalOpen(true);
    };

    const handleSaveProfile = (e: React.FormEvent) => {
        e.preventDefault();
        if (!profileFormData.name) {
            alert('O nome do perfil é obrigatório.');
            return;
        }

        const newProfile: AccessProfile = {
            id: editingProfile ? editingProfile.id : Date.now().toString(),
            name: profileFormData.name,
            permissions: profileFormData.permissions || []
        };

        if (editingProfile) {
            setProfiles(prev => prev.map(p => p.id === editingProfile.id ? newProfile : p));
            // Update permissions of users linked to this profile
            setUsers(prev => prev.map(u => 
                u.profileId === editingProfile.id 
                ? { ...u, permissions: newProfile.permissions } 
                : u
            ));
        } else {
            setProfiles(prev => [...prev, newProfile]);
        }

        setProfileModalOpen(false);
    };

    const handleDeleteProfile = (id: string) => {
        // Check if any user is using this profile
        const isUsed = users.some(u => u.profileId === id);
        if (isUsed) {
            alert('Não é possível excluir este perfil pois existem usuários vinculados a ele.');
            return;
        }

        if (window.confirm('Tem certeza que deseja excluir este perfil de acesso?')) {
            setProfiles(prev => prev.filter(p => p.id !== id));
        }
    };

    const togglePermission = (permissionId: string) => {
        const currentPermissions = profileFormData.permissions || [];
        if (currentPermissions.includes(permissionId)) {
            setProfileFormData(prev => ({
                ...prev,
                permissions: currentPermissions.filter(p => p !== permissionId)
            }));
        } else {
            setProfileFormData(prev => ({
                ...prev,
                permissions: [...currentPermissions, permissionId]
            }));
        }
    };

    // --- HELPERS ---
    const getProfileName = (id?: string) => profiles.find(p => p.id === id)?.name || 'Sem Perfil';

    // Modules available for permission (Flattened for display)
    const availableModules = MENU_ITEMS.map(item => ({
        id: item.id,
        label: item.label,
        subItems: item.children ? item.children.map(c => c.label).join(', ') : null
    }));

    // --- RENDER: VIEW GESTAO ---
    if (view === 'gestao') {
        return (
            <div className="space-y-6">
                <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                    <div>
                        <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                            <UserGroupIcon className="w-8 h-8 text-indigo-600" />
                            Gestão de Usuários
                        </h2>
                        <p className="text-gray-500 dark:text-gray-400 mt-1">
                            Cadastre usuários e atribua seus perfis de acesso.
                        </p>
                    </div>
                    <button
                        onClick={() => handleOpenUserModal()}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors shadow-sm"
                    >
                        <AddIcon className="w-5 h-5" />
                        Novo Usuário
                    </button>
                </div>

                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="min-w-full text-left text-sm">
                            <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider">
                                <tr>
                                    <th className="px-6 py-3">Usuário</th>
                                    <th className="px-6 py-3">Email</th>
                                    <th className="px-6 py-3">Perfil de Acesso</th>
                                    <th className="px-6 py-3">Status</th>
                                    <th className="px-6 py-3 text-center">Ações</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                                {users.map(user => (
                                    <tr key={user.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                        <td className="px-6 py-4 flex items-center gap-3">
                                            <img src={user.avatar} alt={user.name} className="w-10 h-10 rounded-full" />
                                            <span className="font-semibold text-gray-900 dark:text-white">{user.name}</span>
                                        </td>
                                        <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{user.email}</td>
                                        <td className="px-6 py-4">
                                            <span className="px-2 py-1 rounded bg-indigo-50 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-300 text-xs font-semibold border border-indigo-100 dark:border-indigo-800">
                                                {getProfileName(user.profileId)}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4">
                                            <span className={`px-2 py-1 rounded-full text-xs font-semibold ${
                                                user.active 
                                                ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300' 
                                                : 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300'
                                            }`}>
                                                {user.active ? 'Ativo' : 'Inativo'}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-center space-x-2">
                                            <button 
                                                onClick={() => handleOpenUserModal(user)}
                                                className="p-2 text-gray-500 hover:text-indigo-600 transition-colors"
                                                title="Editar"
                                            >
                                                <EditIcon className="w-5 h-5" />
                                            </button>
                                            <button 
                                                onClick={() => handleDeleteUser(user.id)}
                                                className="p-2 text-gray-500 hover:text-red-600 transition-colors"
                                                title="Excluir"
                                            >
                                                <TrashIcon className="w-5 h-5" />
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>

                {isUserModalOpen && (
                    <Modal title={editingUser ? 'Editar Usuário' : 'Novo Usuário'} onClose={() => setUserModalOpen(false)}>
                        <form onSubmit={handleSaveUser} className="space-y-6">
                            <div className="space-y-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Nome Completo</label>
                                    <input 
                                        type="text" 
                                        required 
                                        value={userFormData.name} 
                                        onChange={e => setUserFormData({...userFormData, name: e.target.value})} 
                                        className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 p-2" 
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Email</label>
                                    <input 
                                        type="email" 
                                        required 
                                        value={userFormData.email} 
                                        onChange={e => setUserFormData({...userFormData, email: e.target.value})} 
                                        className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 p-2" 
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Perfil de Acesso</label>
                                    <select 
                                        value={userFormData.profileId} 
                                        onChange={e => setUserFormData({...userFormData, profileId: e.target.value})}
                                        className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 p-2"
                                        required
                                    >
                                        <option value="">Selecione um perfil...</option>
                                        {profiles.map(p => (
                                            <option key={p.id} value={p.id}>{p.name}</option>
                                        ))}
                                    </select>
                                    <p className="mt-1 text-xs text-gray-500">O perfil define quais áreas o usuário pode acessar.</p>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Status</label>
                                    <select 
                                        value={userFormData.active ? 'true' : 'false'} 
                                        onChange={e => setUserFormData({...userFormData, active: e.target.value === 'true'})}
                                        className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 p-2"
                                    >
                                        <option value="true">Ativo</option>
                                        <option value="false">Inativo</option>
                                    </select>
                                </div>
                            </div>

                            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
                                <button 
                                    type="button" 
                                    onClick={() => setUserModalOpen(false)} 
                                    className="px-4 py-2 bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 transition-colors"
                                >
                                    Cancelar
                                </button>
                                <button 
                                    type="submit" 
                                    className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors"
                                >
                                    Salvar Usuário
                                </button>
                            </div>
                        </form>
                    </Modal>
                )}
            </div>
        );
    }

    // --- RENDER: VIEW PERFIS ---
    if (view === 'perfis') {
        return (
            <div className="space-y-6">
                <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                    <div>
                        <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                            <BadgeIcon className="w-8 h-8 text-indigo-600" />
                            Perfis de Acesso
                        </h2>
                        <p className="text-gray-500 dark:text-gray-400 mt-1">
                            Defina os cargos e suas permissões detalhadas no sistema.
                        </p>
                    </div>
                    <button
                        onClick={() => handleOpenProfileModal()}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors shadow-sm"
                    >
                        <AddIcon className="w-5 h-5" />
                        Novo Perfil
                    </button>
                </div>

                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="min-w-full text-left text-sm">
                            <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider">
                                <tr>
                                    <th className="px-6 py-3">Nome do Perfil</th>
                                    <th className="px-6 py-3">Permissões Habilitadas</th>
                                    <th className="px-6 py-3 text-center">Ações</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                                {profiles.map(profile => (
                                    <tr key={profile.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                        <td className="px-6 py-4 font-semibold text-gray-900 dark:text-white">{profile.name}</td>
                                        <td className="px-6 py-4">
                                            <div className="flex flex-wrap gap-1">
                                                {profile.permissions.slice(0, 4).map(p => {
                                                    const mod = availableModules.find(m => m.id === p);
                                                    return (
                                                        <span key={p} className="px-2 py-0.5 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded text-xs border border-gray-200 dark:border-gray-600">
                                                            {mod ? mod.label : p}
                                                        </span>
                                                    )
                                                })}
                                                {profile.permissions.length > 4 && (
                                                    <span className="px-2 py-0.5 bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400 rounded text-xs">
                                                        +{profile.permissions.length - 4}
                                                    </span>
                                                )}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 text-center space-x-2">
                                            <button 
                                                onClick={() => handleOpenProfileModal(profile)}
                                                className="p-2 text-gray-500 hover:text-indigo-600 transition-colors"
                                                title="Editar Permissões"
                                            >
                                                <EditIcon className="w-5 h-5" />
                                            </button>
                                            <button 
                                                onClick={() => handleDeleteProfile(profile.id)}
                                                className="p-2 text-gray-500 hover:text-red-600 transition-colors"
                                                title="Excluir Perfil"
                                            >
                                                <TrashIcon className="w-5 h-5" />
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>

                {isProfileModalOpen && (
                    <Modal title={editingProfile ? 'Editar Perfil de Acesso' : 'Novo Perfil de Acesso'} onClose={() => setProfileModalOpen(false)}>
                        <form onSubmit={handleSaveProfile} className="space-y-6">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Nome do Perfil / Cargo</label>
                                <input 
                                    type="text" 
                                    required 
                                    value={profileFormData.name} 
                                    onChange={e => setProfileFormData({...profileFormData, name: e.target.value})} 
                                    className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 p-2"
                                    placeholder="Ex: Vendedor, Estoquista..."
                                />
                            </div>

                            <div className="space-y-4">
                                <h3 className="text-lg font-semibold text-gray-800 dark:text-white border-b border-gray-200 dark:border-gray-700 pb-2 flex items-center gap-2">
                                    <LockClosedIcon className="w-5 h-5 text-indigo-500" />
                                    Permissões de Menu
                                </h3>
                                <p className="text-sm text-gray-500">Selecione quais itens do menu este perfil pode acessar:</p>

                                <div className="grid grid-cols-1 gap-3 max-h-60 overflow-y-auto pr-2 custom-scrollbar">
                                    {availableModules.map(module => {
                                        const isChecked = profileFormData.permissions?.includes(module.id);
                                        return (
                                            <label 
                                                key={module.id} 
                                                className={`flex items-start gap-3 p-3 rounded-lg border transition-all cursor-pointer ${
                                                    isChecked 
                                                    ? 'bg-indigo-50 border-indigo-200 dark:bg-indigo-900/20 dark:border-indigo-800' 
                                                    : 'bg-gray-50 border-gray-200 dark:bg-gray-700/30 dark:border-gray-600 hover:bg-gray-100 dark:hover:bg-gray-700'
                                                }`}
                                            >
                                                <input 
                                                    type="checkbox" 
                                                    checked={isChecked}
                                                    onChange={() => togglePermission(module.id)}
                                                    className="mt-1 h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                                                />
                                                <div>
                                                    <span className="block text-sm font-semibold text-gray-900 dark:text-white">
                                                        {module.label}
                                                    </span>
                                                    {module.subItems && (
                                                        <span className="block text-xs text-gray-500 dark:text-gray-400 mt-0.5">
                                                            Acesso a: {module.subItems}
                                                        </span>
                                                    )}
                                                </div>
                                            </label>
                                        );
                                    })}
                                </div>
                            </div>

                            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
                                <button 
                                    type="button" 
                                    onClick={() => setProfileModalOpen(false)} 
                                    className="px-4 py-2 bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 transition-colors"
                                >
                                    Cancelar
                                </button>
                                <button 
                                    type="submit" 
                                    className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors"
                                >
                                    Salvar Perfil
                                </button>
                            </div>
                        </form>
                    </Modal>
                )}
            </div>
        );
    }

    return null;
};

export default UsuariosPage;
]]></content>
