import React, { useState, useEffect, useMemo } from 'react';
import { CubeIcon, ClipboardListIcon, ArrowUpIcon, ArrowDownIcon, TrashIcon, ExclamationTriangleIcon, PhotographIcon, SaveIcon, ShoppingCartIcon, AddIcon, EditIcon, SearchIcon } from '../assets/icons';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import type { StockItem, StockMovement, StockMovementType, EstoquePageProps, PurchaseRequest } from '../types';
import { MOCK_STOCK_ITEMS, MOCK_STOCK_MOVEMENTS, MOCK_PURCHASE_REQUESTS } from '../constants';

const EstoquePage: React.FC<EstoquePageProps> = ({ view, setCurrentPage }) => {
    // States
    const [items, setItems] = useState<StockItem[]>([]);
    const [movements, setMovements] = useState<StockMovement[]>([]);
    const [purchaseRequests, setPurchaseRequests] = useState<PurchaseRequest[]>([]);

    // Internal Tab state only for Dashboard view (Visão Geral vs Histórico)
    const [dashboardTab, setDashboardTab] = useState<'lista' | 'movimentacoes'>('lista');

    // Search State
    const [searchTerm, setSearchTerm] = useState('');

    // Modal States
    const [isMoveModalOpen, setMoveModalOpen] = useState(false);
    const [isRequestModalOpen, setRequestModalOpen] = useState(false);

    // Edit Item Modal State
    const [isEditModalOpen, setEditModalOpen] = useState(false);
    const [editingItem, setEditingItem] = useState<StockItem | null>(null);

    // Delete Item Modal State
    const [isDeleteModalOpen, setDeleteModalOpen] = useState(false);
    const [itemToDeleteId, setItemToDeleteId] = useState<string | null>(null);

    // Forms
    const [newItem, setNewItem] = useState<Partial<StockItem>>({ name: '', quantity: 0, minQuantity: 5, unit: 'un', description: '', image: '' });
    const [newMovement, setNewMovement] = useState<Partial<StockMovement>>({ itemId: '', type: 'entrada', quantity: 1, date: new Date().toISOString().split('T')[0], observation: '' });
    const [newRequest, setNewRequest] = useState<Partial<PurchaseRequest>>({ 
        itemId: '', 
        quantity: 1, 
        priority: 'Média', 
        reason: 'Reposição Estoque',
        requester: 'Admin', // Idealmente pegaria do usuário logado
        date: new Date().toISOString().split('T')[0]
    });

    // Load Data
    useEffect(() => {
        const savedItems = localStorage.getItem('stock_items');
        const savedMovements = localStorage.getItem('stock_movements');
        const savedRequests = localStorage.getItem('purchase_requests');

        if (savedItems) setItems(JSON.parse(savedItems));
        else setItems(MOCK_STOCK_ITEMS);

        if (savedMovements) setMovements(JSON.parse(savedMovements));
        else setMovements(MOCK_STOCK_MOVEMENTS);

        if (savedRequests) setPurchaseRequests(JSON.parse(savedRequests));
        else setPurchaseRequests(MOCK_PURCHASE_REQUESTS);
    }, []);

    // Save Data
    useEffect(() => {
        localStorage.setItem('stock_items', JSON.stringify(items));
    }, [items]);

    useEffect(() => {
        localStorage.setItem('stock_movements', JSON.stringify(movements));
    }, [movements]);

    useEffect(() => {
        localStorage.setItem('purchase_requests', JSON.stringify(purchaseRequests));
    }, [purchaseRequests]);

    // Derived Metrics
    const metrics = useMemo(() => {
        const totalItems = items.length;
        const lowStockItems = items.filter(i => i.quantity <= i.minQuantity).length;
        const totalStockValue = items.reduce((acc, i) => acc + i.quantity, 0); // Simplified volume
        return { totalItems, lowStockItems, totalStockValue };
    }, [items]);

    // Filter Items based on search
    const filteredItems = useMemo(() => {
        if (!searchTerm) return items;
        const lowerTerm = searchTerm.toLowerCase();
        return items.filter(item => 
            item.name.toLowerCase().includes(lowerTerm) || 
            (item.description && item.description.toLowerCase().includes(lowerTerm))
        );
    }, [items, searchTerm]);

    // Handlers
    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setNewItem(prev => ({ ...prev, image: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSaveItem = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newItem.name) return;

        const item: StockItem = {
            id: Date.now().toString(),
            name: newItem.name || '',
            quantity: Number(newItem.quantity) || 0,
            minQuantity: Number(newItem.minQuantity) || 0,
            unit: newItem.unit || 'un',
            description: newItem.description,
            image: newItem.image
        };

        setItems(prev => [...prev, item]);
        setNewItem({ name: '', quantity: 0, minQuantity: 5, unit: 'un', description: '', image: '' });
        alert("Produto cadastrado com sucesso!");

        // Redirect to overview after save
        setCurrentPage('ESTOQUE_VISAO_GERAL');
    };

    // Edit Handlers
    const handleOpenEdit = (item: StockItem) => {
        setEditingItem({...item});
        setEditModalOpen(true);
    };

    const handleUpdateItem = (e: React.FormEvent) => {
        e.preventDefault();
        if (!editingItem) return;

        setItems(prev => prev.map(i => i.id === editingItem.id ? editingItem : i));
        setEditModalOpen(false);
        setEditingItem(null);
    };

    const handleDeleteItem = (id: string) => {
        setItemToDeleteId(id);
        setDeleteModalOpen(true);
    };

    const confirmDeleteItem = () => {
        if (itemToDeleteId) {
            setItems(prev => prev.filter(i => i.id !== itemToDeleteId));
            setDeleteModalOpen(false);
            setItemToDeleteId(null);
        }
    }

    const handleSaveMovement = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newMovement.itemId || !newMovement.quantity || !newMovement.type) {
            alert("Preencha todos os campos obrigatórios.");
            return;
        }

        const qty = Number(newMovement.quantity);
        const item = items.find(i => i.id === newMovement.itemId);

        if (!item) return;

        if (newMovement.type === 'saida' && item.quantity < qty) {
            alert("Estoque insuficiente para realizar esta saída.");
            return;
        }

        const movement: StockMovement = {
            id: Date.now().toString(),
            itemId: newMovement.itemId,
            type: newMovement.type as StockMovementType,
            quantity: qty,
            date: newMovement.date || new Date().toISOString().split('T')[0],
            observation: newMovement.observation
        };

        // Update Item Stock
        setItems(prev => prev.map(i => {
            if (i.id === movement.itemId) {
                return {
                    ...i,
                    quantity: movement.type === 'entrada' ? i.quantity + qty : i.quantity - qty
                };
            }
            return i;
        }));

        setMovements(prev => [movement, ...prev]);
        setMoveModalOpen(false);
        setNewMovement({ itemId: '', type: 'entrada', quantity: 1, date: new Date().toISOString().split('T')[0], observation: '' });
    };

    const handleSaveRequest = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newRequest.itemId || !newRequest.quantity) {
            alert("Preencha o item e a quantidade.");
            return;
        }

        const item = items.find(i => i.id === newRequest.itemId);
        if(!item) return;

        const request: PurchaseRequest = {
            id: Date.now().toString(),
            itemId: item.id,
            itemName: item.name,
            quantity: Number(newRequest.quantity),
            unit: item.unit,
            requester: newRequest.requester || 'Admin',
            date: newRequest.date || new Date().toISOString().split('T')[0],
            priority: newRequest.priority as any || 'Média',
            reason: newRequest.reason || 'Reposição Estoque',
            status: 'Pendente',
            observation: newRequest.observation
        };

        setPurchaseRequests(prev => [request, ...prev]);
        setRequestModalOpen(false);
        setNewRequest({ itemId: '', quantity: 1, priority: 'Média', reason: 'Reposição Estoque', requester: 'Admin', date: new Date().toISOString().split('T')[0] });
    };

    const handleUpdateRequestStatus = (id: string, newStatus: PurchaseRequest['status']) => {
        setPurchaseRequests(prev => prev.map(r => r.id === id ? { ...r, status: newStatus } : r));
    }

    const getItemName = (id: string) => items.find(i => i.id === id)?.name || 'Item desconhecido';

    // RENDER: CADASTRO DE PRODUTO
    if (view === 'cadastro') {
        return (
            <div className="p-8 max-w-4xl mx-auto bg-white dark:bg-gray-800 rounded-xl shadow-lg">
                <div className="mb-6 border-b border-gray-200 dark:border-gray-700 pb-4">
                    <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                        <CubeIcon className="w-8 h-8 text-indigo-600" />
                        Cadastro de Novo Material
                    </h2>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">Preencha os dados abaixo para registrar um novo item no controle de estoque.</p>
                </div>

                <form onSubmit={handleSaveItem} className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    {/* Left Column: Image Upload */}
                    <div className="col-span-1 flex flex-col items-center">
                        <label className="cursor-pointer group relative w-full aspect-square max-w-[250px] rounded-xl bg-gray-50 dark:bg-gray-700 flex flex-col items-center justify-center overflow-hidden border-2 border-dashed border-gray-300 dark:border-gray-600 hover:border-indigo-500 hover:bg-indigo-50 dark:hover:bg-gray-600 transition-all">
                            {newItem.image ? (
                                <img src={newItem.image} alt="Preview" className="w-full h-full object-cover" />
                            ) : (
                                <div className="text-center text-gray-400 group-hover:text-indigo-500 p-4">
                                    <PhotographIcon className="w-12 h-12 mx-auto mb-2" />
                                    <span className="text-sm font-medium">Adicionar Foto do Produto</span>
                                    <p className="text-xs mt-1 text-gray-400">Clique para selecionar</p>
                                </div>
                            )}
                            <input type="file" accept="image/*" onChange={handleImageChange} className="hidden" />
                        </label>
                        {newItem.image && (
                            <button 
                                type="button" 
                                onClick={() => setNewItem(prev => ({...prev, image: ''}))}
                                className="mt-2 text-sm text-red-500 hover:text-red-700"
                            >
                                Remover foto
                            </button>
                        )}
                    </div>

                    {/* Right Column: Fields */}
                    <div className="col-span-1 md:col-span-2 space-y-5">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Nome do Item *</label>
                            <input required type="text" value={newItem.name} onChange={e => setNewItem({...newItem, name: e.target.value})} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2.5 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm" placeholder="Ex: Painel Solar 550W" />
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Qtd. Inicial</label>
                                <input type="number" min="0" value={newItem.quantity} onChange={e => setNewItem({...newItem, quantity: Number(e.target.value)})} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2.5 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Unidade de Medida</label>
                                <select value={newItem.unit} onChange={e => setNewItem({...newItem, unit: e.target.value})} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2.5 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm">
                                    <option value="un">Unidade (un)</option>
                                    <option value="kg">Quilo (kg)</option>
                                    <option value="m">Metro (m)</option>
                                    <option value="cx">Caixa (cx)</option>
                                    <option value="pares">Pares</option>
                                    <option value="lt">Litros (lt)</option>
                                    <option value="pc">Peça (pc)</option>
                                </select>
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Estoque Mínimo (Alerta)</label>
                            <div className="relative">
                                <input type="number" min="0" value={newItem.minQuantity} onChange={e => setNewItem({...newItem, minQuantity: Number(e.target.value)})} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2.5 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm" />
                                <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                                    <span className="text-gray-500 text-xs">unidades</span>
                                </div>
                            </div>
                            <p className="mt-1 text-xs text-gray-500">O sistema avisará quando o estoque estiver abaixo deste valor.</p>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Descrição / Detalhes</label>
                            <textarea rows={3} value={newItem.description} onChange={e => setNewItem({...newItem, description: e.target.value})} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2.5 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm" placeholder="Marca, Modelo, Cor, Especificações técnicas..." />
                        </div>

                        <div className="flex justify-end pt-4 gap-3">
                            <button type="button" onClick={() => setCurrentPage('ESTOQUE_VISAO_GERAL')} className="px-5 py-2.5 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors font-medium">Cancelar</button>
                            <button type="submit" className="px-5 py-2.5 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-medium flex items-center gap-2">
                                <SaveIcon className="w-5 h-5" />
                                Salvar Produto
                            </button>
                        </div>
                    </div>
                </form>
            </div>
        );
    }

    // RENDER: SOLICITAÇÃO DE COMPRA
    if (view === 'compras') {
        return (
            <div className="space-y-6">
                <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                     <div>
                        <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                            <ShoppingCartIcon className="w-8 h-8 text-indigo-600" />
                            Solicitações de Compra
                        </h2>
                        <p className="text-gray-500 dark:text-gray-400 mt-1">
                            Acompanhe e registre necessidades de reposição de material.
                        </p>
                    </div>
                    <button
                        onClick={() => setRequestModalOpen(true)}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors shadow-sm"
                    >
                        <AddIcon className="w-5 h-5" />
                        Nova Solicitação
                    </button>
                </div>

                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="min-w-full text-left text-sm">
                             <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider">
                                <tr>
                                    <th className="px-6 py-3">Data</th>
                                    <th className="px-6 py-3">Item</th>
                                    <th className="px-6 py-3">Qtd</th>
                                    <th className="px-6 py-3">Motivo</th>
                                    <th className="px-6 py-3">Solicitante</th>
                                    <th className="px-6 py-3">Prioridade</th>
                                    <th className="px-6 py-3">Status</th>
                                    <th className="px-6 py-3 text-center">Ações</th>
                                </tr>
                             </thead>
                             <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                                {purchaseRequests.map(req => (
                                    <tr key={req.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                        <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{new Date(req.date).toLocaleDateString('pt-BR', { timeZone: 'UTC' })}</td>
                                        <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{req.itemName}</td>
                                        <td className="px-6 py-4 font-bold">{req.quantity} <span className="font-normal text-xs text-gray-500">{req.unit}</span></td>
                                        <td className="px-6 py-4 text-gray-600 dark:text-gray-300 text-xs">{req.reason || '-'}</td>
                                        <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{req.requester}</td>
                                        <td className="px-6 py-4">
                                            <span className={`px-2 py-1 text-xs font-semibold rounded ${
                                                req.priority === 'Alta' ? 'bg-red-100 text-red-800' :
                                                req.priority === 'Média' ? 'bg-yellow-100 text-yellow-800' :
                                                'bg-blue-100 text-blue-800'
                                            }`}>
                                                {req.priority}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4">
                                            <span className={`px-2 py-1 text-xs font-semibold rounded-full ${
                                                req.status === 'Pendente' ? 'bg-gray-200 text-gray-800' :
                                                req.status === 'Aprovado' ? 'bg-blue-200 text-blue-800' :
                                                req.status === 'Comprado' ? 'bg-green-200 text-green-800' :
                                                'bg-red-200 text-red-800'
                                            }`}>
                                                {req.status}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-center space-x-2">
                                            {req.status === 'Pendente' && (
                                                <>
                                                    <button onClick={() => handleUpdateRequestStatus(req.id, 'Aprovado')} className="text-xs bg-blue-50 text-blue-600 px-2 py-1 rounded hover:bg-blue-100">Aprovar</button>
                                                    <button onClick={() => handleUpdateRequestStatus(req.id, 'Cancelado')} className="text-xs bg-red-50 text-red-600 px-2 py-1 rounded hover:bg-red-100">Recusar</button>
                                                </>
                                            )}
                                            {req.status === 'Aprovado' && (
                                                <button onClick={() => handleUpdateRequestStatus(req.id, 'Comprado')} className="text-xs bg-green-50 text-green-600 px-2 py-1 rounded hover:bg-green-100">Marcar Comprado</button>
                                            )}
                                        </td>
                                    </tr>
                                ))}
                                {purchaseRequests.length === 0 && (
                                    <tr>
                                        <td colSpan={8} className="px-6 py-12 text-center text-gray-500">Nenhuma solicitação de compra.</td>
                                    </tr>
                                )}
                             </tbody>
                        </table>
                    </div>
                </div>

                {isRequestModalOpen && (
                    <Modal title="Nova Solicitação de Compra" onClose={() => setRequestModalOpen(false)}>
                        <form onSubmit={handleSaveRequest} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Item Necessário</label>
                                <select required value={newRequest.itemId} onChange={e => setNewRequest({...newRequest, itemId: e.target.value})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500">
                                    <option value="">Selecione o item...</option>
                                    {items.map(i => (
                                        <option key={i.id} value={i.id}>{i.name}</option>
                                    ))}
                                </select>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Quantidade</label>
                                    <input type="number" min="1" required value={newRequest.quantity} onChange={e => setNewRequest({...newRequest, quantity: Number(e.target.value)})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500" />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Prioridade</label>
                                    <select value={newRequest.priority} onChange={e => setNewRequest({...newRequest, priority: e.target.value as any})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500">
                                        <option value="Baixa">Baixa</option>
                                        <option value="Média">Média</option>
                                        <option value="Alta">Alta</option>
                                    </select>
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Motivo</label>
                                <select 
                                    value={newRequest.reason} 
                                    onChange={e => setNewRequest({...newRequest, reason: e.target.value})} 
                                    className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500"
                                >
                                    <option value="Reposição Estoque">Reposição Estoque</option>
                                    <option value="Material Obra">Material Obra</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Observação</label>
                                <textarea rows={2} value={newRequest.observation || ''} onChange={e => setNewRequest({...newRequest, observation: e.target.value})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500" placeholder="Detalhes adicionais..."></textarea>
                            </div>
                            <div className="flex justify-end pt-4 gap-2">
                                <button type="button" onClick={() => setRequestModalOpen(false)} className="px-4 py-2 bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 dark:hover:bg-gray-500 transition-colors">Cancelar</button>
                                <button type="submit" className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors">Solicitar</button>
                            </div>
                        </form>
                    </Modal>
                )}
            </div>
        );
    }

    // RENDER: DASHBOARD (VISÃO GERAL + HISTÓRICO)
    return (
        <div className="space-y-6">
            {/* Cards Overview */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                <DashboardCard title="Total de Itens Cadastrados" value={metrics.totalItems.toString()} icon={CubeIcon} color="bg-blue-500" />
                <DashboardCard title="Itens com Estoque Baixo" value={metrics.lowStockItems.toString()} icon={ExclamationTriangleIcon} color={metrics.lowStockItems > 0 ? "bg-red-500" : "bg-green-500"} />
                <DashboardCard title="Volume Total em Estoque" value={metrics.totalStockValue.toString()} icon={ClipboardListIcon} color="bg-indigo-500" />
            </div>

            {/* Actions & Tabs */}
            <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
                <div className="bg-white dark:bg-gray-800 p-1.5 rounded-lg shadow-sm flex flex-wrap gap-2">
                    <button
                        onClick={() => setDashboardTab('lista')}
                        className={`px-4 py-2 text-sm font-medium rounded-md transition-colors ${dashboardTab === 'lista' ? 'bg-indigo-600 text-white shadow' : 'text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700'}`}
                    >
                        Lista de Produtos
                    </button>
                    <button
                        onClick={() => setDashboardTab('movimentacoes')}
                        className={`px-4 py-2 text-sm font-medium rounded-md transition-colors ${dashboardTab === 'movimentacoes' ? 'bg-indigo-600 text-white shadow' : 'text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700'}`}
                    >
                        Histórico de Movimentações
                    </button>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => setMoveModalOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-gray-800 text-indigo-600 dark:text-indigo-400 border border-indigo-600 dark:border-indigo-400 rounded-md hover:bg-indigo-50 dark:hover:bg-indigo-900/30 transition-colors shadow-sm">
                        <ArrowUpIcon className="w-4 h-4" />
                        <ArrowDownIcon className="w-4 h-4 -ml-2" />
                        Registrar Entrada/Saída
                    </button>
                </div>
            </div>

            {/* Content Area */}
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden min-h-[400px]">

                {/* TAB: LISTA */}
                {dashboardTab === 'lista' && (
                    <>
                        <div className="p-4 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
                            <div className="relative max-w-md">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <SearchIcon className="h-5 w-5 text-gray-400" />
                                </div>
                                <input
                                    type="text"
                                    placeholder="Buscar itens..."
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="block w-full pl-10 pr-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md leading-5 bg-gray-50 dark:bg-gray-700 placeholder-gray-500 focus:outline-none focus:placeholder-gray-400 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm transition duration-150 ease-in-out text-gray-900 dark:text-gray-100"
                                />
                            </div>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="min-w-full text-left text-sm">
                                <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider">
                                    <tr>
                                        <th className="px-6 py-3">Foto</th>
                                        <th className="px-6 py-3">Item</th>
                                        <th className="px-6 py-3">Descrição</th>
                                        <th className="px-6 py-3 text-right">Qtd. Mínima</th>
                                        <th className="px-6 py-3 text-right">Quantidade Atual</th>
                                        <th className="px-6 py-3 text-center">Status</th>
                                        <th className="px-6 py-3 text-center">Ações</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                                    {filteredItems.map(item => (
                                        <tr key={item.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                            <td className="px-6 py-4">
                                                {item.image ? (
                                                    <img src={item.image} alt={item.name} className="w-12 h-12 rounded object-cover shadow-sm border border-gray-200 dark:border-gray-600" />
                                                ) : (
                                                    <div className="w-12 h-12 rounded bg-gray-100 dark:bg-gray-700 flex items-center justify-center text-gray-400 border border-gray-200 dark:border-gray-600">
                                                        <PhotographIcon className="w-6 h-6" />
                                                    </div>
                                                )}
                                            </td>
