    <content><![CDATA[
// FIX: Import React to provide the 'React' namespace for React.ComponentType.
import React from 'react';

export type Page = 'DASHBOARD' | 'ORCAMENTO' | 'FINANCEIRO_VISAO_GERAL' | 'FINANCEIRO_CATEGORIAS' | 'FINANCEIRO_DRE' | 'RELATORIOS_VISAO_GERAL' | 'RELATORIOS_NOVO' | 'RELATORIOS_STATUS' | 'RELATORIOS_HISTORICO' | 'RELATORIOS_CONFIG' | 'NOVO_ORCAMENTO' | 'ESTOQUE_VISAO_GERAL' | 'ESTOQUE_NOVO_PRODUTO' | 'ESTOQUE_COMPRAS' | 'USUARIOS_GESTAO' | 'USUARIOS_PERFIS' | 'USUARIOS';

export interface MenuItem {
  id: Page | string; // Allow string for parent menu items that don't map to a page
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  children?: MenuItem[];
}

export interface AccessProfile {
    id: string;
    name: string;
    permissions: string[]; // List of Page IDs or Module IDs allowed
}

export interface User {
    id: string;
    name: string;
    email: string;
    role: 'admin' | 'user'; // Mantido para compatibilidade, mas o controle real será via profileId
    profileId?: string; // ID do AccessProfile
    avatar?: string;
    permissions: string[]; // Legacy: mantido para não quebrar lógica antiga, mas será derivado do perfil
    active: boolean;
}

export interface Transaction {
  id: string;
  name: string;
  date: string;
  amount: number;
  status: 'Aprovado' | 'Pendente' | 'Recusado';
}

export interface OrcamentoVariant {
    id: string;
    name: string;
    isPrincipal: boolean;
    formState: any;
    calculated: any;
}

export interface SavedOrcamento {
    id: number;
    savedAt: string;
    // Legacy fields (para compatibilidade com dados antigos)
    formState?: any;
    calculated?: any;
    // New structure
    variants?: OrcamentoVariant[];
}

export interface OrcamentoPageProps {
    setCurrentPage: (page: Page) => void;
    onEdit: (orcamento: SavedOrcamento) => void;
}

export interface NovoOrcamentoPageProps {
    setCurrentPage: (page: Page) => void;
    orcamentoToEdit: SavedOrcamento | null;
    clearEditingOrcamento: () => void;
}

// Tipos para a nova página Financeiro
export type FinancialTransactionType = 'receita' | 'despesa';
export type FinancialTransactionStatus = 'pendente' | 'pago';

export interface FinancialCategory {
    id: string;
    name: string;
    type: FinancialTransactionType;
}

export interface FinancialTransaction {
    id: string;
    description: string;
    amount: number;
    type: FinancialTransactionType;
    dueDate: string; // YYYY-MM-DD
    paymentDate?: string; // YYYY-MM-DD
    launchDate?: string; // YYYY-MM-DD - Data de Lançamento/Competência
    categoryId: string;
    status: FinancialTransactionStatus;
}

export interface FinanceiroPageProps {
    view: 'dashboard' | 'categorias' | 'dre';
}

// Types for Estoque (Inventory)
export interface StockItem {
    id: string;
    name: string;
    quantity: number;
    minQuantity: number;
    unit: string; // e.g., 'un', 'kg', 'm'
    description?: string;
    image?: string; // Base64 string for the product image
}

export type StockMovementType = 'entrada' | 'saida';

export interface StockMovement {
    id: string;
    itemId: string;
    type: StockMovementType;
    quantity: number;
    date: string; // YYYY-MM-DD
    observation?: string;
}

export interface PurchaseRequest {
    id: string;
    itemId: string;
    itemName: string; // denormalized for easier display when item might be deleted
    quantity: number;
    unit: string;
    requester: string;
    date: string; // YYYY-MM-DD
    priority: 'Baixa' | 'Média' | 'Alta';
    status: 'Pendente' | 'Aprovado' | 'Comprado' | 'Cancelado';
    observation?: string;
    reason?: string;
}

export interface EstoquePageProps {
    view: 'dashboard' | 'cadastro' | 'compras';
    setCurrentPage: (page: Page) => void;
}

// Relatórios
export interface ExpenseReportItem {
    id: string;
    date: string;
    description: string;
    origin: string;
    destination: string;
    km: number;
    toll: number;
}

export type ExpenseReportStatus = 'Rascunho' | 'Em Aberto' | 'Transferido' | 'Pago';

export interface ExpenseReport {
    id: string;
    requester: string;
    sector: string;
    period: string; // String formatada para exibição (ex: "01/01/2024 a 31/01/2024")
    periodStart?: string; // YYYY-MM-DD
    periodEnd?: string; // YYYY-MM-DD
    items: ExpenseReportItem[];
    kmValueUsed: number;
    status: ExpenseReportStatus;
    createdAt: string; // ISO String
    totalValue: number;
}

export interface RelatoriosPageProps {
    view: 'analise' | 'reembolso' | 'config' | 'historico' | 'status';
    reportToEdit?: ExpenseReport | null;
    clearReportToEdit?: () => void;
    onSave?: () => void; // Callback to navigate after save
    onEditReport?: (report: ExpenseReport) => void; // Callback to switch to edit view
}

export interface UsuariosPageProps {
    view: 'gestao' | 'perfis';
}
]]></content>
